:root {
      --bg: #ffffff;
      --surface: #ffffff;
      --user-bubble: #f0f4f9;
      --ink: #1f1f1f;
      --muted: #444746;
      --line: rgba(0, 0, 0, 0.08);
      --line-strong: rgba(0, 0, 0, 0.14);
      --shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
      --font-kurdish: "Noto Sans Arabic", sans-serif;
    }

    html.dark {
      --bg: #131314;
      --surface: #1e1f20;
      --user-bubble: #282a2c;
      --ink: #e3e3e3;
      --muted: #c4c7c5;
      --line: rgba(255, 255, 255, 0.08);
      --line-strong: rgba(255, 255, 255, 0.15);
      --shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { width: 100%; height: 100%; background: var(--bg); color: var(--ink); font-family: var(--font-kurdish); overflow: hidden; }
    .app-layout { display: flex; width: 100%; height: 100dvh; position: relative; }

    /* سایدبار */
    .sidebar { width: 292px; height: 100%; background: color-mix(in srgb, var(--bg) 98%, var(--user-bubble)); border-left: 1px solid var(--line); display: flex; flex-direction: column; padding: 20px 16px 14px; gap: 18px; z-index: 100; transition: transform 0.3s cubic-bezier(0.2, 0, 0, 1); }
    .brand-header { display: flex; align-items: center; gap: 11px; padding: 0 2px 18px; border-bottom: 1px solid var(--line); }
    .brand-logo { width: 34px; height: 34px; background: #000; border-radius: 8px; display: grid; place-items: center; overflow: hidden; }
    .brand-logo img { width: 100%; height: 100%; display: block; object-fit: cover; }
    .brand-mark { width: 100%; height: 100%; display: grid; place-items: center; color: #fff; font-size: 18px; font-weight: 800; line-height: 1; }
    .brand-mark { background-image: url("data:image/png;base64,"); background-position: center; background-repeat: no-repeat; background-size: cover; }
    .brand-mark::before { content: none; }
    .brand-title { font-size: 19px; font-weight: 800; letter-spacing: -.3px; }
    .new-chat-btn { display: flex; align-items: center; justify-content: center; gap: 9px; padding: 10px 14px; border-radius: 10px; background: var(--user-bubble); border: 1px solid var(--line-strong); color: var(--ink); font-size: 13px; font-weight: 700; cursor: pointer; transition: background .2s, border-color .2s, transform .2s; }
    .new-chat-btn:hover { background: var(--surface); border-color: var(--ink); transform: translateY(-1px); }
    .new-chat-btn span { font-size: 19px; line-height: 12px; font-weight: 400; }
    .menu-section-title { display: flex; align-items: center; color: var(--muted); font-size: 10px; font-weight: 800; padding: 0 5px 8px; letter-spacing: .5px; }
    .history-list, .tools-list { overflow-y: auto; display: flex; flex-direction: column; gap: 3px; }
    .history-list { flex: 1; min-height: 80px; padding: 2px 4px; }
    .history-empty { display: none; }
    .tools-list { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 2px; padding: 3px 0 11px; border-bottom: 1px solid var(--line); background: transparent; overflow: hidden; }
    .menu-item { position: relative; display: flex; flex: 0 0 44px; flex-direction: column; align-items: center; justify-content: center; gap: 6px; width: 44px; height: 44px; min-width: 0; padding: 8px 2px; border: 0; border-radius: 9px; background: transparent; color: var(--muted); text-align: center; font: inherit; font-size: 10px; cursor: pointer; transition: background .2s, color .2s, transform .2s; }
    .tools-list .menu-item span, .settings-theme span { display: none; }
    .menu-item:hover { background: var(--user-bubble); color: var(--ink); transform: translateY(-1px); }
    .menu-item svg { width: 17px; height: 17px; flex: 0 0 17px; color: var(--muted); transition: color .2s; }
    .menu-item:hover svg { color: var(--ink); }
    .settings-theme { display: flex; align-items: center; width: 44px; border: 0; background: transparent; color: var(--muted); font: inherit; cursor: pointer; flex: 0 0 44px; flex-direction: column; justify-content: center; gap: 6px; padding: 8px 2px; border-top: 0; border-radius: 9px; font-size: 10px; text-align: center; }
    .settings-theme:hover { background: var(--user-bubble); }
    .sidebar-footer { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 7px; }
    .footer-caption, .useful-note { display: none; }
    .history-search { display: flex; align-items: center; gap: 8px; margin: 0 4px 8px; padding: 8px 4px; border-bottom: 1px solid var(--line-strong); color: var(--muted); }
    .history-search svg { width: 15px; height: 15px; flex: 0 0 15px; }
    .history-search input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--ink); font: inherit; font-size: 12px; }
    .history-search input::placeholder { color: var(--muted); opacity: .85; }
    .theme-toggle-btn svg { width: 17px; height: 17px; flex: 0 0 17px; color: var(--muted); }
    .theme-toggle-btn:hover { background: var(--user-bubble); }
    .scrim { display: none; position: fixed; inset: 0; background: rgba(0, 0, 0, 0.4); z-index: 90; }

    /* بەشی سەرەکی */
    .main-content { flex: 1; height: 100%; display: flex; flex-direction: column; position: relative; }
    .topbar { height: 60px; display: flex; align-items: center; padding: 0 16px; z-index: 10; }
    .menu-btn { display: none; background: transparent; border: 0; color: var(--ink); cursor: pointer; padding: 8px; }

    /* شوێنی چات */
    .chat-container { flex: 1; overflow-y: auto; padding: 20px 16px 140px; display: flex; flex-direction: column; align-items: center; }
    .welcome-box { margin: auto 0; text-align: center; animation: welcomeRise 1.35s cubic-bezier(.22,.61,.36,1) both; }
    .welcome-box .brand-logo { width: 48px; height: 48px; background: transparent; border-radius: 0; overflow: visible; animation: welcomeLogo 1.8s cubic-bezier(.22,.61,.36,1) both; box-shadow: none; }
    .welcome-box .brand-mark { width: 48px; height: 48px; border-radius: 14px; background: var(--ink); color: var(--bg); font-size: 24px; box-shadow: 0 8px 20px rgba(0,0,0,.12); background-image: inherit; }
    .welcome-box h1 { font-size: 28px; font-weight: 700; margin-top: 12px; background: linear-gradient(105deg, #1f1f1f 0%, #1f1f1f 36%, #aeb4bb 50%, #1f1f1f 64%, #1f1f1f 100%); background-size: 280% 100%; -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; animation: welcomeTextShimmer 4.8s ease-in-out 0.8s infinite; }
    html.dark .welcome-box h1 { background: linear-gradient(105deg, #ffffff 0%, #ffffff 36%, #c4c9cf 50%, #ffffff 64%, #ffffff 100%); background-size: 280% 100%; -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
    @keyframes welcomeRise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes welcomeLogo { 0% { opacity: 0; transform: translateY(8px) scale(.94); filter: blur(2px); } 60% { opacity: .82; filter: blur(.4px); } 100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); } }
    @keyframes welcomeTextShimmer { 0%, 25% { background-position: 120% 0; } 65%, 100% { background-position: -20% 0; } }
    .messages-stream { width: min(800px, 100%); display: flex; flex-direction: column; gap: 32px; }
    .message-bubble { display: flex; align-items: flex-start; gap: 13px; width: 100%; }
    .message-bubble.user, .message-bubble.assistant { justify-content: flex-start; }
    .assistant-avatar { width: 40px; height: 40px; background: transparent; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; overflow: hidden; margin-top: 1px; filter: drop-shadow(0 2px 4px rgba(0,0,0,.08)); }
    .assistant-avatar img { width: 100%; height: 100%; display: block; object-fit: cover; }
    .assistant-avatar .brand-mark, .thinking-anim .brand-mark { width: 100%; height: 100%; border-radius: 50%; background: var(--ink); color: var(--bg); font-size: 19px; background-image: inherit; }
    .user-avatar-placeholder { width: 36px; height: 36px; flex-shrink: 0; }
    .message-content-wrapper { display: flex; flex-direction: column; max-width: calc(100% - 52px); }
    .user .text-content { background: var(--user-bubble); color: var(--ink); padding: 14px 20px; border-radius: 8px 24px 24px 24px; line-height: 1.7; font-size: 15px; width: fit-content; }
    .assistant .text-content { background: transparent; color: var(--ink); padding: 4px 0 0 0; line-height: 1.85; font-size: 15px; }
    .thinking-anim { width: 40px; height: 40px; background: transparent; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0; overflow: hidden; margin-top: 1px; filter: drop-shadow(0 2px 4px rgba(0,0,0,.08)); }
    .thinking-anim img { width: 100%; height: 100%; display: block; object-fit: cover; }
    .assistant-name { display: flex; align-items: center; min-height: 40px; color: var(--ink); font-size: 15px; font-weight: 800; line-height: 1.45; margin-bottom: 3px; letter-spacing: -0.15px; }
    .assistant .text-content { padding-top: 0; }
    .thinking-text { width: fit-content; color: var(--muted); font-size: 14px; line-height: 1.7; font-weight: 500; white-space: nowrap; background: linear-gradient(105deg, var(--muted) 0%, var(--muted) 36%, #fff 50%, var(--muted) 64%, var(--muted) 100%); background-size: 260% 100%; -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; animation: textShimmer 1.8s cubic-bezier(.4,0,.2,1) infinite; }
    .thinking-dots { display: inline-flex; direction: ltr; gap: 1px; margin-inline-start: 5px; vertical-align: middle; -webkit-text-fill-color: var(--muted); }
    .thinking-dots i { font-style: normal; display: inline-block; font-size: 18px; line-height: 10px; animation: dotBounce 1.05s ease-in-out infinite; }
    .thinking-dots i:nth-child(2) { animation-delay: 0.14s; }
    .thinking-dots i:nth-child(3) { animation-delay: 0.28s; }
    @keyframes textShimmer { 0% { background-position: 150% 0; } 100% { background-position: -50% 0; } }
    @keyframes dotBounce { 0%, 60%, 100% { transform: translateY(0); } 30% { transform: translateY(-5px); } }
    @keyframes pulseGlow { 0% { transform: scale(0.9); box-shadow: 0 0 0 0 rgba(0,0,0,0.2); } 100% { transform: scale(1.1); box-shadow: 0 0 15px 5px rgba(0,0,0,0.1); } }
    @keyframes pulseGlowDark { 0% { transform: scale(0.9); box-shadow: 0 0 0 0 rgba(255,255,255,0.2); } 100% { transform: scale(1.1); box-shadow: 0 0 15px 5px rgba(255,255,255,0.1); } }
    .action-bar { display: flex; gap: 4px; margin-top: 12px; opacity: 0; transition: opacity 0.5s ease; }
    .action-bar.show { opacity: 1; }
    .action-bar button { background: transparent; border: none; color: var(--muted); padding: 8px; border-radius: 50%; cursor: pointer; transition: background 0.2s; display: grid; place-items: center; }
    .action-bar button:hover { background: var(--user-bubble); color: var(--ink); }
    .action-bar svg { width: 18px; height: 18px; }

    /* ✨ بۆکسی نووسینی پێشکەوتوو و دوگمەی ناردن */
    .composer-container { position: fixed; bottom: max(16px, env(safe-area-inset-bottom)); left: 0; right: 0; width: min(800px, calc(100% - 32px)); margin: 0 auto; z-index: 50; }
    
    .composer-box {
      display: flex; 
      align-items: flex-end; /* هێشتنەوەی دوگمەکان لە خوارەوە کاتێک بۆکسەکە گەورە دەبێت */
      gap: 12px;
      background: rgba(255, 255, 255, 0.75);
      backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
      border: 1px solid var(--line-strong);
      border-radius: 28px; /* ڕێکخستنی شێوەی حەبی بۆ ئەوەی گونجاو بێت لەگەڵ گەورەبوون */
      padding: 10px 16px;
      box-shadow: var(--shadow); 
      transition: all 0.3s ease;
    }
    html.dark .composer-box { background: rgba(30, 31, 32, 0.75); }
    
    /* درەوشانەوەی نەرمی مۆدێرن لە کاتی کرتەکردندا */
    .composer-box:focus-within { 
      box-shadow: 0 0 0 1px transparent, 0 12px 36px rgba(0,0,0,0.12); 
      border-color: transparent; 
      background: rgba(255, 255, 255, 0.95);
    }
    html.dark .composer-box:focus-within { 
      box-shadow: 0 0 0 1px transparent, 0 12px 36px rgba(0,0,0,0.5);
      background: rgba(30, 31, 32, 0.95);
    }

    .composer-box textarea { flex: 1; max-height: 150px; min-height: 24px; border: 0; background: transparent; color: var(--ink); font-family: inherit; font-size: 15px; line-height: 1.6; resize: none; outline: none; padding: 6px 0; }
    .composer-box textarea::placeholder { color: var(--muted); }
    
    .action-btn { background: transparent; border: 0; color: var(--muted); cursor: pointer; width: 36px; height: 36px; display: grid; place-items: center; border-radius: 50%; flex-shrink: 0; transition: background 0.2s ease, color 0.2s ease; margin-bottom: 2px; }
    .action-btn:hover { background: var(--user-bubble); color: var(--ink); }

    /* کۆنتڕۆڵکردنی شوێنی دوگمەکانی چەپ */
    .left-actions { position: relative; width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; margin-bottom: 2px; }

    /* دوگمەی دەنگ */
    .mic-btn { position: absolute; transition: all 0.25s cubic-bezier(0.2, 0, 0, 1); opacity: 1; transform: scale(1); visibility: visible; }
    .mic-btn.hidden { opacity: 0; transform: scale(0.6); visibility: hidden; }

    /* ✨ دوگمەی ناردنی پڕکراو بە ئەنیمەیشن */
    .send-btn { 
      position: absolute;
      background: var(--ink); 
      color: var(--bg); 
      width: 36px; height: 36px; 
      border-radius: 50%; 
      display: grid; place-items: center;
      border: 0; cursor: pointer;
      transition: all 0.25s cubic-bezier(0.2, 0, 0, 1);
      /* لە سەرەتادا نادیارە و بچووکە */
      opacity: 0; transform: scale(0.6); visibility: hidden;
    }
    .send-btn:hover { background: var(--muted); color: var(--bg); }
    .send-btn.visible { opacity: 1; transform: scale(1); visibility: visible; }

    @media (max-width: 768px) {
      .menu-btn { display: block; } .sidebar { position: fixed; top: 0; right: 0; transform: translateX(100%); } .sidebar.open { transform: translateX(0); } .sidebar.open + .scrim { display: block; }
      .chat-container { padding-top: 10px; } .composer-box { padding: 8px 12px; } .message-content-wrapper { max-width: calc(100% - 46px); }
    }
    /* مینۆی سادەی AI ـی پێشکەوتوو */
    .sidebar { width: 280px; padding: 18px 14px 12px; gap: 14px; background: var(--bg); border-left: 1px solid var(--line); }
    .brand-header { padding: 0 6px 16px; gap: 10px; border-bottom: 1px solid var(--line); }
    .brand-logo { width: 34px; height: 34px; border-radius: 9px; box-shadow: none; }
    .brand-title { font-size: 18px; letter-spacing: -.2px; }
    .menu-section-title { color: var(--muted); font-size: 11px; font-weight: 700; padding: 4px 8px 8px; }
    .tools-list { display: none; }
    .history-search { margin: 0 4px 8px; padding: 0 4px; height: 34px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--muted); }
    .history-search:focus-within { border-bottom-color: var(--line-strong); box-shadow: none; }
    .history-search input { font-size: 12px; }
    .new-chat-btn { height: 40px; border-radius: 10px; padding: 0 12px; background: var(--user-bubble); border: 1px solid var(--line); color: var(--ink); box-shadow: none; }
    .new-chat-btn:hover { background: var(--surface); border-color: var(--line-strong); transform: none; }
    .sidebar-footer { padding-top: 8px; border-top: 1px solid var(--line); }
    .footer-caption, .useful-note { display: none; }
    .settings-theme { display: flex; align-items: center; width: 100%; height: 36px; border: 0; background: transparent; color: var(--ink); font: inherit; cursor: pointer; flex-direction: row; justify-content: flex-start; gap: 10px; padding: 8px; border-radius: 8px; font-size: 12px; text-align: right; }
    .settings-theme span { display: inline; }
    .settings-theme:hover { background: var(--user-bubble); }
    .settings-theme svg { width: 16px; height: 16px; color: var(--muted); }
    /* unified AI sidebar refinement */
    .sidebar { width: 288px; padding: 22px 16px 16px; gap: 16px; background: #f8f8f7; border-left: 1px solid #e8e8e6; }
    html.dark .sidebar { background: #191a1b; border-left-color: #2b2c2d; }
    .brand-header { padding: 0 6px 4px; border-bottom: 0; }
    .brand-logo { width: 32px; height: 32px; border-radius: 8px; }
