    .new-chat-btn { order: 0; height: 42px; justify-content: flex-start; padding: 0 13px; gap: 10px; border-radius: 9px; background: #202122; border-color: #202122; color: #fff; box-shadow: none; }
    .new-chat-btn:hover { background: #111; border-color: #111; }
    html.dark .new-chat-btn { background: #f0f0ee; border-color: #f0f0ee; color: #18191a; }
    .new-chat-btn span { font-size: 20px; }
    .menu-section-title { padding: 5px 8px 7px; color: #858789; font-size: 10px; font-weight: 700; letter-spacing: .2px; }
    html.dark .menu-section-title { color: #999b9e; }
    .history-search { height: 36px; margin: 0 2px 4px; padding: 0 10px; border: 1px solid #e2e2e0; border-radius: 9px; background: #fff; color: #8c8e91; }
    html.dark .history-search { border-color: #303133; background: #202122; }
    .history-search:focus-within { border-color: #b6b7b8; box-shadow: 0 0 0 2px rgba(0,0,0,.035); }
    .history-list { padding: 0 2px; }
    .sidebar-footer { gap: 2px; padding-top: 12px; border-top: 1px solid #e5e5e3; }
    html.dark .sidebar-footer { border-top-color: #2c2d2f; }
