    html.dark .settings-theme { color: #c1c3c5; }
    .settings-theme:hover { background: #ededeb; }
    html.dark .settings-theme:hover { background: #242526; }
    /* final product-grade sidebar system */
    .sidebar { width: 272px; padding: 20px 14px 14px; gap: 12px; background: #fafaf9; border-left: 1px solid #ededeb; }
    html.dark .sidebar { background: #171819; border-left-color: #292a2b; }
    .brand-header { height: 42px; padding: 0 8px; gap: 10px; }
    .brand-logo { width: 30px; height: 30px; border-radius: 8px; }
    .brand-title { font-size: 17px; font-weight: 750; }
    .new-chat-btn { height: 40px; padding: 0 12px; border: 0; border-radius: 8px; background: transparent; color: var(--ink); font-size: 13px; font-weight: 650; box-shadow: none; }
    .new-chat-btn:hover { background: #eeeeec; border: 0; transform: none; }
    html.dark .new-chat-btn:hover { background: #242526; }
    .new-chat-btn span { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border: 1px solid var(--line-strong); border-radius: 6px; font-size: 17px; }
