    html.dark .history-search { border-bottom-color: #303133; background: transparent; }
    .history-search:focus-within { border-bottom-color: #9b9d9f; box-shadow: none; }
    .history-list { padding: 0 2px; }
    .history-list:empty::after { content: "هێشتا گفتوگۆیەک نییە"; display: block; padding: 18px 8px; color: var(--muted); font-size: 11px; text-align: center; opacity: .7; }
    .sidebar-footer { gap: 1px; padding: 10px 2px 0; border-top: 1px solid #e8e8e6; }
    html.dark .sidebar-footer { border-top-color: #2a2b2c; }
    .settings-theme { height: 36px; padding: 0 9px; border-radius: 7px; color: #626568; font-size: 12px; }
    html.dark .settings-theme { color: #b5b7b9; }
    .settings-theme:hover { background: #eeeeec; }
    html.dark .settings-theme:hover { background: #242526; }
    .sidebar-footer { display: grid; grid-template-columns: repeat(3, 1fr); align-items: stretch; gap: 4px; }
    .settings-theme, .profile-btn { width: 100%; height: 48px; padding: 5px 2px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; border-radius: 8px; color: #626568; font-size: 10px; text-align: center; }
    html.dark .settings-theme, html.dark .profile-btn { color: #b5b7b9; }
    .settings-theme svg, .profile-btn svg { width: 17px; height: 17px; color: currentColor; }
    .sidebar-footer .settings-theme span, .sidebar-footer .profile-btn span { display: none; }
    .sidebar-footer .settings-theme, .sidebar-footer .profile-btn { height: 42px; padding: 0; gap: 0; }
    .sidebar-footer .settings-theme svg, .sidebar-footer .profile-btn svg { width: 18px; height: 18px; }
    .theme-sun { display: none; }
    html.dark .theme-moon { display: none; }
    html.dark .theme-sun { display: block; }
    .profile-btn { border: 0; background: transparent; font: inherit; cursor: pointer; }
    .profile-btn:hover { background: #eeeeec; }
    html.dark .profile-btn:hover { background: #242526; }
    /* app-wide visual system */
    .main-content { background: var(--bg); transition: background .25s ease, color .25s ease; }
    .topbar { height: 56px; padding: 0 20px; }
    .topbar { position: relative; display: flex; align-items: center; justify-content: flex-start; border-bottom: 0; }
    .topbar .menu-btn { display: grid; place-items: center; width: 36px; height: 36px; padding: 6px; border-radius: 8px; color: var(--muted); line-height: 0; transition: background .2s, color .2s; }
    .topbar .menu-btn svg { display: block; width: 24px; height: 24px; }
    .topbar .menu-btn:hover { background: var(--app-control); color: var(--ink); }
    .topbar::after { content: none; }
