    @keyframes assistantIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes responseReveal { from { opacity: 0; filter: blur(3px); transform: translateY(3px); } to { opacity: 1; filter: blur(0); transform: translateY(0); } }
    @keyframes responseCursor { 0%, 48% { opacity: 1; } 49%, 100% { opacity: 0; } }
    @keyframes thinkingPulse { 0%, 100% { opacity: .72; transform: scale(.97); } 50% { opacity: 1; transform: scale(1); } }
    @keyframes thinkingRing { to { transform: rotate(360deg); } }
    @keyframes thinkingDot { 0%, 65%, 100% { opacity: .28; transform: translateY(0); } 35% { opacity: 1; transform: translateY(-2px); } }
    .message-bubble.assistant .assistant-name { display: flex; align-items: center; height: 40px; min-height: 40px; margin: 0 0 5px; line-height: 1; }
