.topbar {
  position: relative !important;
  height: 112px !important;
  min-height: 112px !important;
  padding: 20px 28px !important;
  display: grid !important;
  grid-template-columns: 1fr auto 1fr !important;
  align-items: start !important;
  background: transparent !important;
  border: 0 !important;
}
.top-brand { grid-column: 1; justify-self: start; display: flex; flex-direction: row; align-items: center; gap: 12px; direction: ltr; }
.top-brand-mark { width: 58px; height: 58px; border-radius: 18px; display: grid; place-items: center; border: 1px solid rgba(94, 142, 255, .42); background: linear-gradient(145deg, rgba(37, 57, 123, .95), rgba(25, 29, 82, .9)); box-shadow: 0 0 26px rgba(75, 107, 255, .20), inset 0 0 18px rgba(77, 124, 255, .16); overflow: hidden; }
.top-brand-mark .brand-mark { width: 100%; height: 100%; }
.top-brand-title { color: #fff; font-size: 36px; line-height: 1; font-weight: 800; letter-spacing: -1px; }

.plan-switcher { grid-column: 2; justify-self: center; position: relative; z-index: 80; }
.plan-trigger { width: 220px !important; height: 58px !important; border-radius: 30px !important; border: 1px solid rgba(78, 144, 255, .43) !important; background: rgba(8, 27, 66, .86) !important; color: #fff !important; box-shadow: inset 0 0 18px rgba(49, 104, 222, .09), 0 0 18px rgba(42, 104, 230, .08) !important; font-size: 20px !important; font-weight: 800 !important; display: flex !important; align-items: center !important; justify-content: center !important; gap: 18px !important; }
.plan-trigger-chevron { order: 2 !important; width: 38px !important; height: 38px !important; border-radius: 50%; display: grid !important; place-items: center; background: rgba(30, 75, 156, .72); }
.plan-trigger-chevron svg { width: 19px; height: 19px; }
.plan-trigger > span:first-child:not(.plan-trigger-chevron) { order: 1; }
.plan-menu { top: 64px !important; border-color: rgba(87, 154, 255, .32) !important; background: rgba(8, 24, 56, .98) !important; box-shadow: 0 20px 55px rgba(0,0,0,.38), 0 0 30px rgba(48, 108, 255, .10) !important; }
.plan-option { color: #fff !important; }
.plan-option small { color: #93a9d1 !important; }

.header-theme-toggle { grid-column: 3; justify-self: end; width: 116px; height: 58px; border: 1px solid rgba(95, 120, 169, .38); border-radius: 30px; display: flex; align-items: center; justify-content: space-around; padding: 6px 9px; cursor: pointer; background: linear-gradient(120deg, rgba(240,245,255,.96), rgba(210,221,241,.96)); color: #5e6b86; box-shadow: 0 0 22px rgba(153, 176, 229, .12); font: inherit; }
.header-theme-toggle .theme-orb { width: 38px; height: 42px; border-radius: 50%; background: linear-gradient(180deg, #a675ff, #8658ed); box-shadow: 0 0 16px rgba(150, 100, 255, .48); }
.header-theme-toggle .theme-moon, .header-theme-toggle .theme-sun { font-size: 25px; line-height: 1; }
.menu-btn { display: grid !important; grid-column: 3; justify-self: end; width: 58px !important; height: 58px !important; margin-inline-start: 130px; margin-top: 0; border: 1px solid rgba(76, 136, 242, .36) !important; border-radius: 18px !important; background: rgba(8, 27, 65, .68) !important; color: #fff !important; box-shadow: 0 0 18px rgba(37, 103, 235, .08); }
