.chat-container { padding: 20px 22px 190px !important; align-items: center !important; }
.messages-stream { display: flex; }
.welcome-box { width: min(660px, 100%); margin: 0 auto !important; padding: 6px 0 18px; text-align: center; position: relative; animation: zhirWelcomeIn .75s ease both; }
@keyframes zhirWelcomeIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.welcome-orbit { position: relative; width: min(610px, 94vw); height: 330px; margin: 0 auto -8px; pointer-events: none; }
.orbit-line { position: absolute; left: 50%; top: 50%; width: 92%; height: 52%; border: 1px solid rgba(61, 126, 239, .35); border-radius: 50%; transform: translate(-50%,-50%) rotate(-9deg); box-shadow: 0 0 16px rgba(47, 106, 245, .08); }
.orbit-line-b { width: 82%; height: 43%; transform: translate(-50%,-50%) rotate(12deg); border-color: rgba(122, 80, 255, .26); }
.orbit-dot { position: absolute; width: 9px; height: 9px; border-radius: 50%; box-shadow: 0 0 15px currentColor; }
.orbit-dot-1 { left: 15%; top: 53%; color: #35dffb; background: currentColor; }
.orbit-dot-2 { right: 14%; top: 45%; color: #b66aff; background: currentColor; }
.orbit-dot-3 { right: 24%; bottom: 14%; color: #6ba8ff; background: currentColor; }
.welcome-float { position: absolute; width: 94px; height: 94px; display: grid; place-items: center; border: 1px solid rgba(78, 129, 235, .48); border-radius: 26px; background: linear-gradient(145deg, rgba(20, 49, 105, .88), rgba(11, 24, 62, .96)); color: #52e8ff; box-shadow: 0 0 28px rgba(42, 176, 255, .28), inset 0 0 20px rgba(41, 89, 180, .18); transform: rotate(-5deg); }
.welcome-float svg { width: 44px; height: 44px; }
