.welcome-float-brain { left: 3%; bottom: 5%; color: #48e8e4; box-shadow: 0 0 32px rgba(35, 229, 220, .27); transform: rotate(-7deg); }
.welcome-float-bulb { right: 3%; bottom: 3%; color: #ffca48; box-shadow: 0 0 32px rgba(255, 183, 51, .30); transform: rotate(7deg); }
.welcome-core { position: absolute; left: 50%; top: 76px; transform: translateX(-50%); width: 278px; height: 278px; padding: 25px; border-radius: 62px; background: linear-gradient(145deg, rgba(232, 239, 255, .96), rgba(166, 181, 224, .86)); border: 1px solid rgba(225, 239, 255, .95); box-shadow: 0 0 35px rgba(102, 151, 255, .25), 0 20px 45px rgba(0,0,0,.24), inset 0 0 25px rgba(255,255,255,.55); }
.welcome-core-inner { width: 100%; height: 100%; border-radius: 42px; display: grid; place-items: center; background: linear-gradient(145deg, rgba(221, 231, 250, .9), rgba(181, 196, 232, .78)); border: 1px solid rgba(177, 198, 237, .8); box-shadow: inset 0 0 20px rgba(94, 126, 194, .10); }
.welcome-peace { width: 166px; height: 166px; display: grid; place-items: center; border-radius: 42px; background: rgba(250, 251, 255, .96); color: #070707; font-family: Arial, sans-serif; font-size: 100px; line-height: 1; text-rendering: geometricPrecision; box-shadow: 0 8px 18px rgba(37, 58, 104, .08); }
.welcome-copy { position: relative; z-index: 3; margin: -2px auto 24px; max-width: 640px; }
.welcome-copy h1 { margin: 0 0 8px !important; color: #fff !important; font-size: clamp(30px, 5vw, 48px) !important; font-weight: 900 !important; letter-spacing: -1px; background: linear-gradient(100deg, #4edfff 4%, #b46aff 48%, #7fa6ff 92%); -webkit-background-clip: text !important; background-clip: text !important; -webkit-text-fill-color: transparent !important; animation: none !important; }
.welcome-copy h1 span { background: linear-gradient(100deg, #9c6aff, #b874ff, #63dfff); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.welcome-copy p { margin: 0 auto; color: #9eb0d1; font-size: 16px; line-height: 2; max-width: 560px; }
.welcome-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; position: relative; z-index: 4; }
.welcome-card { min-height: 164px; position: relative; padding: 18px 16px 16px; text-align: right; direction: rtl; border-radius: 22px; border: 1px solid rgba(67, 131, 238, .42); background: linear-gradient(145deg, rgba(15, 39, 86, .82), rgba(7, 23, 56, .92)); color: #fff; cursor: pointer; font-family: inherit; box-shadow: inset 0 0 22px rgba(45, 91, 171, .08), 0 10px 25px rgba(0,0,0,.14); transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease; }
