/* ============================================================
   Final theme + mobile topbar correction
   Only CSS: keeps all existing HTML/JS behavior unchanged.
   ============================================================ */

/* Shared page colors: Light */
html:not(.dark) {
  --zhir-bg: #f5f8ff;
  --zhir-bg-2: #edf3ff;
  --zhir-panel: rgba(255, 255, 255, .82);
  --zhir-line: rgba(63, 112, 205, .22);
  --zhir-text: #1f2937;
  --zhir-muted: #66738b;
  --app-canvas: #f7f9fd;
  --app-panel: #ffffff;
  --app-control: #eef3fb;
  --app-border: #d9e2f0;
  --app-border-hover: #b9c9e1;
  --app-subtle: #65738b;
}

/* Shared page colors: Dark */
html.dark {
  --zhir-bg: #06122e;
  --zhir-bg-2: #0b1838;
  --zhir-panel: rgba(12, 29, 66, .78);
  --zhir-line: rgba(87, 163, 255, .34);
  --zhir-text: #f5f7ff;
  --zhir-muted: #9aaed0;
  --app-canvas: #0b1530;
  --app-panel: #101d3c;
  --app-control: #17284d;
  --app-border: rgba(104, 151, 235, .25);
  --app-border-hover: rgba(125, 169, 245, .48);
  --app-subtle: #a9b9d5;
}

/* The complete page follows the selected theme. */
html:not(.dark) body,
html:not(.dark) .app-layout,
html:not(.dark) .main-content,
html:not(.dark) .chat-container {
  background:
    radial-gradient(circle at 50% 30%, rgba(91, 142, 255, .10), transparent 30%),
    radial-gradient(circle at 82% 78%, rgba(168, 91, 255, .08), transparent 28%),
    var(--zhir-bg) !important;
  color: var(--zhir-text) !important;
}

html.dark body,
html.dark .app-layout,
html.dark .main-content,
html.dark .chat-container {
  background:
    radial-gradient(circle at 50% 33%, rgba(37, 83, 170, .18), transparent 30%),
    radial-gradient(circle at 80% 78%, rgba(133, 41, 221, .16), transparent 30%),
    var(--zhir-bg) !important;
  color: var(--zhir-text) !important;
}

/* Sidebar, dialogs and common panels use the same theme tokens. */
.sidebar,
.profile-dialog,
.api-key-dialog,
.upgrade-dialog,
.plan-menu {
  background: var(--app-panel) !important;
  color: var(--ink) !important;
  border-color: var(--app-border) !important;
}

.sidebar-footer,
.brand-header {
  border-color: var(--app-border) !important;
}

.history-search,
.new-chat-btn,
.profile-summary,
.profile-field input,
.payment-method,
.upgrade-plan-card,
.plan-detail-card {
  background: var(--app-control) !important;
  color: var(--ink) !important;
  border-color: var(--app-border) !important;
}

.history-search input,
.profile-field input,
.plan-option,
.plan-option strong,
.plan-option small {
  color: var(--ink) !important;
}

/* Light-mode welcome area: no dark cards/backgrounds remain. */
html:not(.dark) .top-brand-title,
html:not(.dark) .welcome-copy h1,
html:not(.dark) .welcome-card strong {
  color: var(--ink) !important;
}

html:not(.dark) .top-brand-mark {
  background: linear-gradient(145deg, #eaf1ff, #dbe6fb) !important;
  border-color: rgba(70, 116, 204, .28) !important;
  box-shadow: 0 0 24px rgba(75, 107, 255, .12), inset 0 0 18px rgba(77, 124, 255, .10) !important;
}

html:not(.dark) .plan-trigger {
  background: rgba(255, 255, 255, .92) !important;
  color: var(--ink) !important;
  border-color: rgba(78, 144, 255, .34) !important;
  box-shadow: 0 6px 22px rgba(48, 84, 150, .10) !important;
}

html:not(.dark) .plan-menu {
  background: rgba(255, 255, 255, .98) !important;
  box-shadow: 0 20px 55px rgba(34, 58, 96, .16), 0 0 30px rgba(48, 108, 255, .07) !important;
}

html:not(.dark) .plan-option:hover,
html:not(.dark) .plan-option.selected {
  background: var(--app-control) !important;
}

html:not(.dark) .menu-btn {
  background: rgba(255, 255, 255, .90) !important;
  color: var(--ink) !important;
  border-color: rgba(76, 136, 242, .28) !important;
  box-shadow: 0 6px 18px rgba(37, 103, 235, .08) !important;
}

html.dark .header-theme-toggle {
  background: linear-gradient(120deg, rgba(19, 31, 60, .98), rgba(27, 42, 78, .98)) !important;
  color: #b9c8e2 !important;
  border-color: rgba(95, 120, 169, .32) !important;
}

html:not(.dark) .welcome-float {
  background: linear-gradient(145deg, rgba(231, 240, 255, .96), rgba(210, 224, 248, .94)) !important;
  border-color: rgba(78, 129, 235, .34) !important;
  box-shadow: 0 8px 28px rgba(42, 110, 220, .14), inset 0 0 20px rgba(255,255,255,.65) !important;
}

html:not(.dark) .welcome-card {
  background: linear-gradient(145deg, rgba(255,255,255,.96), rgba(234,241,252,.96)) !important;
  color: var(--ink) !important;
  border-color: rgba(67, 131, 238, .34) !important;
  box-shadow: inset 0 0 22px rgba(45, 91, 171, .05), 0 10px 25px rgba(44, 75, 130, .08) !important;
}

html:not(.dark) .welcome-card small,
html:not(.dark) .welcome-copy p,
html:not(.dark) .welcome-status {
  color: var(--muted) !important;
}

html:not(.dark) .card-arrow {
  background: rgba(62, 112, 211, .12) !important;
  color: #315da8 !important;
}

html:not(.dark) .composer-box {
  background: rgba(255, 255, 255, .94) !important;
  border-color: var(--app-border) !important;
  color: var(--ink) !important;
  box-shadow: 0 10px 32px rgba(44, 75, 130, .12), inset 0 0 18px rgba(91, 142, 255, .05) !important;
}

html.dark .composer-box {
  background: rgba(16, 29, 60, .94) !important;
  border-color: var(--app-border) !important;
  color: var(--ink) !important;
}

/* Mobile: real flex layout, no absolute left/right positioning. */
@media (max-width: 768px) {
  .topbar {
    position: relative !important;
    display: flex !important;
    flex-direction: row !important;
    direction: rtl !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 8px !important;
    width: 100% !important;
    height: 64px !important;
    min-height: 64px !important;
    padding: 8px 10px !important;
  }

  .topbar .menu-btn {
    position: static !important;
    inset: auto !important;
    right: auto !important;
    left: auto !important;
    top: auto !important;
    order: 1 !important;
    flex: 0 0 44px !important;
    width: 44px !important;
    height: 44px !important;
    margin: 0 !important;
  }

  .topbar .top-brand {
    position: static !important;
    inset: auto !important;
    right: auto !important;
    left: auto !important;
    top: auto !important;
    order: 2 !important;
    flex: 0 0 auto !important;
    margin: 0 !important;
  }

  .topbar .plan-switcher {
    position: static !important;
    inset: auto !important;
    left: auto !important;
    right: auto !important;
    top: auto !important;
    transform: none !important;
    order: 3 !important;
    flex: 1 1 auto !important;
    min-width: 0 !important;
    display: flex !important;
    justify-content: center !important;
    margin: 0 !important;
  }

  .topbar .header-theme-toggle {
    position: static !important;
    inset: auto !important;
    right: auto !important;
    left: auto !important;
    top: auto !important;
    order: 4 !important;
    flex: 0 0 86px !important;
    width: 86px !important;
    height: 44px !important;
    margin: 0 !important;
  }

  .top-brand-mark {
    width: 44px !important;
    height: 44px !important;
    border-radius: 14px !important;
  }

  .top-brand-title {
    font-size: 26px !important;
  }

  .plan-trigger {
    width: min(168px, 100%) !important;
    height: 44px !important;
    font-size: 16px !important;
    gap: 10px !important;
  }

  .plan-trigger-chevron {
    width: 30px !important;
    height: 30px !important;
  }
}

@media (max-width: 430px) {
  .topbar {
    gap: 6px !important;
    padding-inline: 8px !important;
  }

  .topbar .menu-btn {
    flex-basis: 40px !important;
    width: 40px !important;
    height: 40px !important;
    border-radius: 13px !important;
  }

  .topbar .header-theme-toggle {
    flex-basis: 74px !important;
    width: 74px !important;
    height: 40px !important;
    padding-inline: 6px !important;
  }

  .topbar .top-brand-mark {
    width: 40px !important;
    height: 40px !important;
  }

  .topbar .top-brand-title {
    display: none !important;
  }

  .topbar .plan-trigger {
    width: min(150px, 100%) !important;
    height: 40px !important;
    font-size: 15px !important;
    gap: 7px !important;
  }

  .topbar .plan-trigger-chevron {
    width: 27px !important;
    height: 27px !important;
  }

  .header-theme-toggle .theme-moon,
  .header-theme-toggle .theme-sun {
    font-size: 19px !important;
  }

  .header-theme-toggle .theme-orb {
    width: 28px !important;
    height: 31px !important;
  }
}
